import math


def round_half_even(x):
    floor_x = math.floor(x)
    diff = x - floor_x

    if diff < 0.5:
        return int(floor_x)
    if diff > 0.5:
        return int(floor_x + 1)

    # Exactly halfway: round to the nearest even integer.
    if floor_x % 2 == 0:
        return int(floor_x)
    return int(floor_x + 1)

